@router.get("/health")
async def health(request: Request):
    results = {}
    for name, backend in request.app.state.backends.items():
        results[name] = await backend.health()
    overall = "ok" if any(results.values()) else "degraded"
    return {"status": overall, "backends": results, "version": "0.0.1"}

from __future__ import annotations

from collections.abc import AsyncIterator

import httpx

from local2api.errors import BackendUnavailable


class HTTPBackendAdapter:
    def __init__(self, name: str, url: str, timeout: float) -> None:
        self.name = name
        self.url = url
        self.timeout = timeout

    async def request(self, body: dict) -> httpx.Response:
        try:
            async with httpx.AsyncClient(timeout=self.timeout) as client:
                return await client.post(self.url, json=body)
        except httpx.HTTPError as exc:
            raise BackendUnavailable(f"{self.name} backend unavailable: {exc}") from exc

    async def _stream(self, body: dict) -> AsyncIterator[bytes]:
        try:
            async with httpx.AsyncClient(timeout=self.timeout) as client:
                async with client.stream("POST", self.url, json=body) as response:
                    if response.is_error:
                        payload = await response.aread()
                        raise BackendUnavailable(
                            f"{self.name} stream failed with HTTP {response.status_code}: {payload[:200]!r}"
                        )
                    async for chunk in response.aiter_raw():
                        if chunk:
                            yield chunk
        except httpx.HTTPError as exc:
            raise BackendUnavailable(f"{self.name} backend unavailable: {exc}") from exc

    def stream(self, body: dict) -> AsyncIterator[bytes]:
        return self._stream(body)

    async def health(self) -> bool:
        try:
            async with httpx.AsyncClient(timeout=min(self.timeout, 2.0)) as client:
                response = await client.get(self.url.rsplit("/v1/chat/completions", 1)[0] or "/")
                return response.status_code < 500
        except httpx.HTTPError:
            return False

from __future__ import annotations

import os
from dataclasses import dataclass


def _env_int(name: str, default: int) -> int:
    try:
        return int(os.getenv(name, str(default)))
    except ValueError:
        return default


def _env_float(name: str, default: float) -> float:
    try:
        return float(os.getenv(name, str(default)))
    except ValueError:
        return default


@dataclass(frozen=True)
class Settings:
    host: str = os.getenv("LOCAL2API_HOST", "127.0.0.1")
    port: int = _env_int("LOCAL2API_PORT", 8000)
    local_url: str = os.getenv("LOCAL_LLM_URL", "http://127.0.0.1:8080/v1/chat/completions")
    cloud_url: str = os.getenv("CLOUD_API_URL", "http://127.0.0.1:3000/v1/chat/completions")
    local_model: str = os.getenv("LOCAL_LLM_MODEL", "local-model")
    cloud_model: str = os.getenv("CLOUD_API_MODEL", "cloud-model")
    local_timeout: float = _env_float("LOCAL_TIMEOUT_SECONDS", 60.0)
    cloud_timeout: float = _env_float("CLOUD_TIMEOUT_SECONDS", 120.0)
    complexity_words: int = _env_int("ROUTER_COMPLEXITY_WORDS", 450)

class BackendError(RuntimeError):
    """Base exception raised when a backend cannot serve a request."""


class BackendUnavailable(BackendError):
    """Backend cannot be reached or failed before a valid response."""


class UnsafeFallback(BackendError):
    """The selected task must not silently degrade to a weaker backend."""

from __future__ import annotations

from collections.abc import Iterable

from .types import RoutingDecision

LOCAL_TASK_HINTS = {
    "autocomplete",
    "complete this line",
    "rewrite",
    "proofread",
    "summarize",
    "rename variable",
    "format code",
}

CLOUD_TASK_HINTS = {
    "architecture",
    "architect",
    "multi-file",
    "repository",
    "repo-wide",
    "refactor",
    "race condition",
    "algorithm",
    "deep debug",
    "optimize system",
    "security review",
}

SAFE_LOCAL_FALLBACK_HINTS = {
    "rewrite",
    "proofread",
    "summarize",
    "autocomplete",
    "complete this line",
    "format code",
}


class RuleRouter:
    """Deterministic v0.0.1 router."""

    def __init__(self, complexity_words: int = 450) -> None:
        self.complexity_words = complexity_words

    @staticmethod
    def _text(messages: Iterable[dict]) -> str:
        chunks: list[str] = []
        for message in messages:
            content = message.get("content", "")
            if isinstance(content, str):
                chunks.append(content)
            elif isinstance(content, list):
                for item in content:
                    if isinstance(item, dict) and item.get("type") == "text":
                        chunks.append(str(item.get("text", "")))
        return " ".join(chunks).lower()

    def decide(self, body: dict) -> RoutingDecision:
        requested_model = str(body.get("model", "local2api-auto")).lower()
        if requested_model in {"local", "local2api-local"}:
            return RoutingDecision("local", "explicit_model_override", "none", 1.0)
        if requested_model in {"cloud", "local2api-cloud"}:
            return RoutingDecision("cloud", "explicit_model_override", "none", 1.0)

        text = self._text(body.get("messages", []))
        word_count = len(text.split())
        cloud_hits = [hint for hint in CLOUD_TASK_HINTS if hint in text]
        local_hits = [hint for hint in LOCAL_TASK_HINTS if hint in text]

        if cloud_hits:
            fallback = "safe" if any(h in text for h in SAFE_LOCAL_FALLBACK_HINTS) else "none"
            return RoutingDecision("cloud", f"complex_task:{cloud_hits[0]}", fallback, 0.95)

        if word_count > self.complexity_words:
            return RoutingDecision("cloud", "large_context", "safe", 0.75)

        if local_hits:
            return RoutingDecision("local", f"local_task:{local_hits[0]}", "none", 0.9)

        return RoutingDecision("local", "default_low_cost", "none", 0.6)

from __future__ import annotations

import json
from collections.abc import AsyncIterator

import httpx

from local2api.errors import BackendUnavailable


class FakeBackend:
    def __init__(self, name: str, status: int = 200, fail: bool = False) -> None:
        self.name = name
        self.status = status
        self.fail = fail
        self.calls: list[dict] = []

    async def request(self, body: dict) -> httpx.Response:
        self.calls.append(body)
        if self.fail:
            raise BackendUnavailable(f"{self.name} is down")
        payload = {
            "id": f"fake-{self.name}",
            "object": "chat.completion",
            "choices": [{"index": 0, "message": {"role": "assistant", "content": self.name}}],
        }
        return httpx.Response(self.status, json=payload)

    async def _stream(self, body: dict) -> AsyncIterator[bytes]:
        self.calls.append(body)
        if self.fail:
            raise BackendUnavailable(f"{self.name} is down")
        chunk = {"choices": [{"delta": {"content": self.name}}]}
        yield f"data: {json.dumps(chunk)}\n\n".encode()
        yield b"data: [DONE]\n\n"

    def stream(self, body: dict) -> AsyncIterator[bytes]:
        return self._stream(body)

    async def health(self) -> bool:
        return not self.fail

from local2api.routing.router import RuleRouter


def test_short_request_defaults_local():
    decision = RuleRouter().decide({"messages": [{"role": "user", "content": "fix typo"}]})
    assert decision.backend == "local"


def test_architecture_routes_cloud_without_silent_fallback():
    decision = RuleRouter().decide(
        {"messages": [{"role": "user", "content": "review repository architecture"}]}
    )
    assert decision.backend == "cloud"
    assert decision.fallback_mode == "none"


def test_explicit_model_override():
    decision = RuleRouter().decide({"model": "cloud", "messages": []})
    assert decision.backend == "cloud"
    assert decision.reason == "explicit_model_override"
